export async function ci_runs(context, params) {
    try {
        const runs = await context.listRuns(params);
        return JSON.stringify({
            total: runs.total,
            page: runs.page,
            perPage: runs.perPage,
            runs: runs.items.map(r => ({
                id: r.id,
                name: r.name,
                status: r.status,
                conclusion: r.conclusion,
                branch: r.headBranch,
                sha: r.headSha,
                url: r.url,
                createdAt: r.createdAt,
            })),
        });
    }
    catch (error) {
        return JSON.stringify({
            error: error instanceof Error ? error.message : 'Unknown error',
        });
    }
}
